/* spkFecha() del prototipo: la fecha que muestra el tooltip por punto. */
function spkFechas(periodo, N) {
  const out = [];
  for (let i = 0; i < N; i++) {
    const ult = i === N - 1;
    if (periodo === 'hoy') {
      out.push(['8 AM', '9 AM', '10 AM', '11 AM', '12 PM', '1 PM', '2 PM', '3 PM', '4 PM', '5 PM', '6 PM', 'ahora'][i] || 'ahora');
      continue;
    }
    if (periodo === 'd90') {
      out.push(ult ? 'hoy' : ['abr', 'abr', 'abr', 'may', 'may', 'may', 'jun', 'jun', 'jun', 'jul', 'jul'][i]);
      continue;
    }
    const mes = periodo === 'junio' ? 'jun' : 'jul';
    if (ult) {
      out.push(periodo === 'junio' ? '30 jun' : 'hoy');
      continue;
    }
    out.push(1 + Math.round(i * 29 / (N - 1)) + ' ' + mes);
  }
  return out;
}
